trait Stage {
    fn apply(&mut self, value: i32) -> i32;
}

struct Counter {
    calls: i32,
}

impl Stage for Counter {
    fn apply(&mut self, value: i32) -> i32 {
        self.calls += 1;
        value + self.calls
    }
}

fn main() {
    let mut stages: Vec<Box<dyn Stage>> = vec![Box::new(Counter { calls: 0 })];
    for input in [10, 10, 10] {
        let mut v = input;
        for s in stages.iter_mut() {
            v = s.apply(v);
        }
        println!("{v}");
    }
}

