        "A"
    }
}

impl State for B {
    fn next(self: Box<Self>) -> Box<dyn State> {
        self
    }

    fn name(&self) -> &'static str {
        "B"
    }
}

fn main() {
    let mut state: Option<Box<dyn State>> = Some(Box::new(A));
    if let Some(s) = state.___() {
        state = Some(s.next());
    }
